content.text:
{
  "name": "光束挡板",
  "name_en": "Beam Stopper",
  "manufacturer": "",
  "description": "用于束线或实验光路中的插入/移出式挡板设备。该类设备通过外部控制信号执行打开与关闭，并结合进位/退位限位开关判断当前位置；部分变体仅提供状态读取，用于光路联锁显示与通光状态判断。",
  "description_en": "An insertable/removable beamline stopper used in experimental beam paths. It is opened and closed via external control signals, and its position is determined from in/out limit switches; some variants are status-only and are used for lightpath display and transmission-state evaluation.",
  "actions": [
    {
      "action_name": "auto-open",
      "description": "打开挡板，使光路处于放行状态。",
      "description_en": "Open the stopper to allow the beam path to pass."
    },
    {
      "action_name": "auto-close",
      "description": "关闭挡板，将挡板插入光路以阻断通光。",
      "description_en": "Close the stopper, inserting it into the beam path to block transmission."
    },
    {
      "action_name": "auto-check_value",
      "description": "检查输入值是否对应有效的挡板状态或命令值。",
      "description_en": "Check whether an input value corresponds to a valid stopper state or command value."
    },
    {
      "action_name": "auto-calc_lightpath_state",
      "description": "根据进位和退位限位信号计算当前光路状态。",
      "description_en": "Calculate the current lightpath state from the inserted and removed limit-switch signals."
    }
  ],
  "tag_hints": [
    "beamline stopper",
    "lightpath state",
    "limit switches",
    "beam blocking",
    "PV control",
    "safety shutter"
  ]
}

